const now = new Date();
const weekday = new Intl.DateTimeFormat('en-US', {
  timeZone: 'Asia/Taipei',
  weekday: 'long',
}).format(now);

const dateText = new Intl.DateTimeFormat('zh-TW', {
  timeZone: 'Asia/Taipei',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(now);

const dailyItems = [
  '鑰匙', '錢包', '平板', '鍵盤', '水壺',
  '衛生紙', '耳機', '鉛筆盒', '學生證',
];

const weeklyItems = {
  Monday: ['機率資料夾（功課）', '電腦', '滑鼠', '電腦充電線'],
  Tuesday: ['初等資料夾（功課）', '電腦', '滑鼠'],
  Wednesday: ['電腦', '滑鼠'],
  Thursday: ['電腦', '滑鼠', '電腦充電線'],
  Friday: ['機率資料夾'],
  Saturday: [],
  Sunday: [],
};

const items = [...new Set([
  ...dailyItems,
  ...(weeklyItems[weekday] || []),
])];

const events = $input.all().map(item => item.json).filter(e => Object.keys(e).length > 0);

const time = value => {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  return new Intl.DateTimeFormat('zh-TW', {
    timeZone: 'Asia/Taipei',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).format(date);
};

const eventLines = events.map(event => {
  const title = event.summary || event.title || '（未命名行程）';
  const start = event.start?.dateTime || event.start?.date || event.startTime;
  const end = event.end?.dateTime || event.end?.date || event.endTime;

  if (!start) return `• ${title}`;

  const startTime = time(start);
  const endTime = time(end);

  if (!startTime) return `• 全天／${title}`;
  return `• ${startTime}${endTime ? `–${endTime}` : ''} ${title}`;
});

const message = [
  `☀️ 今日提醒｜${dateText}`,
  '',
  '📅 今日行程',
  ...(eventLines.length ? eventLines : ['• 今天沒有查到行程']),
  '',
  '🎒 出門必帶',
  ...items.map(item => `☐ ${item}`),
].join('\n');

return [{
  json: {
    message,
    weekday,
    dateText,
    eventCount: events.length,
  }
}];
